local _, BUI = ...

BUI.PlatynatorProfileDate = "August 13, 2026 00:00"

BUI.PlatynatorProfileString = "PLATY!1!"


function BUI.ImportPlatynatorProfile()
	if not (Platynator and Platynator.API and Platynator.API.ImportString) then return false end

	BUI.db.global.platynatorImportedDate = BUI.PlatynatorProfileDate

	local function reportError(errorMessage) geterrorhandler()(errorMessage); return errorMessage end
	local profileImported, profileError = xpcall(Platynator.API.ImportString, reportError, BUI.PlatynatorProfileString, 'BluUI')
	if not profileImported then
		BUI.Print('Platynator import failed: ' .. tostring(profileError))
		return false
	end

	BUI.Print("Platynator profile 'BluUI' imported!")
	return true
end